#!/bin/sh
# Phosphorus Linux: self-contained payload; no root privileges or shell startup edits.
set -eu
umask 077
WITH_AI=0
NO_OPEN=0
EXTRACT=''
while [ "$#" -gt 0 ]; do
  case "$1" in
    --with-ai) WITH_AI=1;;
    --no-open) NO_OPEN=1;;
    --extract) shift; EXTRACT=${1:?Podaj folder po --extract};;
    --help) printf '%s\n' 'Instalacja: sh Phosphorus-Linux-1.7.0.sh [--with-ai] [--no-open]' 'Samo wypakowanie: sh Phosphorus-Linux-1.7.0.sh --extract FOLDER'; exit 0;;
    *) printf 'Nieznana opcja: %s\n' "$1" >&2; exit 1;;
  esac
  shift
done
fail(){ printf '\nPhosphorus: %s\n' "$*" >&2; exit 1; }
for utility in tar gzip base64 sha256sum awk mktemp; do command -v "$utility" >/dev/null 2>&1 || fail "Brakuje programu: $utility"; done
WORK=$(mktemp -d "${TMPDIR:-/tmp}/phosphorus-install.XXXXXXXX")
cleanup(){ case "$WORK" in */phosphorus-install.*) [ ! -L "$WORK" ] && rm -rf -- "$WORK";; esac; }
trap cleanup EXIT
trap 'exit 129' HUP
trap 'exit 130' INT
trap 'exit 143' TERM
awk 'payload{print} /^__PHOSPHORUS_ARCHIVE_BELOW__$/{payload=1}' "$0" | base64 -d > "$WORK/payload.tar.gz"
printf '%s  %s\n' '67531051e5075de5fe4fc4e9cbc66a5aa44188fdca6f21d6fcab6eb155954456' "$WORK/payload.tar.gz" | sha256sum -c - >/dev/null || fail 'Uszkodzony instalator. Pobierz plik ponownie.'
if [ -n "$EXTRACT" ]; then mkdir -p -- "$EXTRACT"; tar -xzf "$WORK/payload.tar.gz" -C "$EXTRACT"; printf 'Wypakowano do: %s\n' "$EXTRACT"; exit 0; fi
[ "$(uname -s)" = Linux ] || fail 'Ten instalator jest przeznaczony dla Linuxa.'
[ "$(id -u)" != 0 ] || fail 'Uruchom instalator na swoim zwykłym koncie, bez sudo.'
: "${HOME:?Brak katalogu domowego}"
PREFIX=${PHOSPHORUS_PREFIX:-${XDG_DATA_HOME:-$HOME/.local/share}/phosphorus}
BIN_DIR=${PHOSPHORUS_BIN_DIR:-$HOME/.local/bin}
case "$PREFIX" in /*) ;; *) fail 'PHOSPHORUS_PREFIX musi być ścieżką absolutną.';; esac
case "$PREFIX" in *'
'*|*'='*) fail 'Ścieżka instalacji zawiera nieobsługiwany znak.';; esac
[ ! -L "$PREFIX" ] || fail 'Folder instalacji nie może być dowiązaniem.'
case "$BIN_DIR" in /*) ;; *) fail 'PHOSPHORUS_BIN_DIR musi być ścieżką absolutną.';; esac
mkdir -p -- "$PREFIX/releases" "$PREFIX/runtime" "$BIN_DIR" "${XDG_DATA_HOME:-$HOME/.local/share}/applications"
chmod 700 "$PREFIX"
node_ok(){ "$1" --input-type=module -e 'if(Number(process.versions.node.split(".")[0])<24)process.exit(1);await import("node:sqlite");await import("node:zlib").then(z=>{if(!z.createZstdDecompress)process.exit(1)})' >/dev/null 2>&1; }
NODE=''
if command -v node >/dev/null 2>&1 && node_ok "$(command -v node)"; then NODE=$(command -v node); fi
if [ -z "$NODE" ] && [ -f "$PREFIX/node-path" ]; then PREVIOUS=$(cat "$PREFIX/node-path"); if node_ok "$PREVIOUS"; then NODE=$PREVIOUS; fi; fi
download(){
  if command -v curl >/dev/null 2>&1; then curl --fail --location --proto '=https' --proto-redir '=https' --retry 2 --connect-timeout 20 --output "$2" "$1";
  elif command -v wget >/dev/null 2>&1; then wget --https-only -O "$2" "$1";
  else fail 'Zainstaluj curl lub wget i uruchom instalator ponownie.'; fi
}
if [ -z "$NODE" ]; then
  case "$(uname -m)" in x86_64|amd64) ARCH=x64;; aarch64|arm64) ARCH=arm64;; *) fail 'Zainstaluj Node.js 24+ dla swojej architektury i uruchom instalator ponownie.';; esac
  printf '%s\n' 'Przygotowanie Node.js 24 LTS…'
  download 'https://nodejs.org/dist/latest-v24.x/SHASUMS256.txt' "$WORK/SHASUMS256.txt"
  FILE=$(awk -v arch="$ARCH" '$2 ~ "^node-v24\\.[0-9]+\\.[0-9]+-linux-" arch "\\.tar\\.gz$" {print $2;exit}' "$WORK/SHASUMS256.txt")
  [ -n "$FILE" ] || fail 'Nie znaleziono odpowiedniego Node.js na serwerze producenta.'
  NODE_VERSION=${FILE%%-linux-*}
  NODE_VERSION=${NODE_VERSION#node-}
  download "https://nodejs.org/dist/$NODE_VERSION/$FILE" "$WORK/$FILE"
  (cd "$WORK" && awk -v name="$FILE" '$2==name{print}' SHASUMS256.txt | sha256sum -c -) || fail 'Suma kontrolna Node.js jest nieprawidłowa.'
  tar -xzf "$WORK/$FILE" -C "$WORK"
  node_ok "$WORK/${FILE%.tar.gz}/bin/node" || fail 'Pobrany Node.js nie działa na tym Linuxie. Na Alpine/musl zainstaluj Node.js 24+ z repozytorium dystrybucji.'
  RUNTIME="$PREFIX/runtime/${FILE%.tar.gz}"
  if [ ! -d "$RUNTIME" ]; then mv -- "$WORK/${FILE%.tar.gz}" "$RUNTIME"; fi
  NODE="$RUNTIME/bin/node"
fi
RELEASE="$PREFIX/releases/1.7.0-$(date +%s)-$$"
mkdir -- "$RELEASE"
tar -xzf "$WORK/payload.tar.gz" -C "$RELEASE"
"$NODE" "$RELEASE/runtime/validate.mjs" "$RELEASE" || fail 'Nieprawidłowa zawartość paczki.'
# Stop only the prior, authenticated Phosphorus instance before switching the release.
if [ -f "$PREFIX/launcher.sh" ]; then sh "$PREFIX/launcher.sh" --stop || fail 'Poprzedni serwer nadal działa. Zakończ go przed aktualizacją.'; fi
printf '%s\n' "$NODE" > "$PREFIX/node-path.next"
printf '%s\n' "$RELEASE" > "$PREFIX/release-path.next"
mv -f -- "$PREFIX/node-path.next" "$PREFIX/node-path"
mv -f -- "$PREFIX/release-path.next" "$PREFIX/release-path"
cp -- "$RELEASE/runtime/launcher.sh" "$PREFIX/launcher.sh"
cp -- "$RELEASE/System/public/favicon.svg" "$PREFIX/icon.svg"
chmod 700 "$PREFIX/launcher.sh"
# A wrapper instead of a symlink keeps paths containing spaces intact.
"$NODE" "$RELEASE/runtime/validate.mjs" --wrapper "$PREFIX/launcher.sh" "$BIN_DIR/phosphorus"
chmod 700 "$BIN_DIR/phosphorus"
"$NODE" "$RELEASE/runtime/launcher.mjs" --desktop-entry "$PREFIX/launcher.sh" "$PREFIX/icon.svg" "${XDG_DATA_HOME:-$HOME/.local/share}/applications/pl.qwdqwxx.phosphorus.desktop"
if command -v update-desktop-database >/dev/null 2>&1; then update-desktop-database "${XDG_DATA_HOME:-$HOME/.local/share}/applications" >/dev/null 2>&1 || :; fi
printf '\n%s\n' 'Phosphorus Linux 1.7.0 został zainstalowany.' 'Uruchamianie: ikona Phosphorus w menu aplikacji albo:'
printf '  "%s/phosphorus"\n' "$BIN_DIR"
if [ "$WITH_AI" = 1 ]; then "$PREFIX/launcher.sh" --setup-ai || fail 'Aplikacja jest zainstalowana, ale AI nie jest jeszcze gotowe. Wznów: phosphorus --setup-ai'; fi
if [ "$NO_OPEN" != 1 ]; then "$PREFIX/launcher.sh"; fi
exit 0
